VALUES
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000061', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000061', '-', '')), 'Dương Thị Thúy', 'Thợ điện dân dụng, 10 năm trong nghề, nhận việc nhỏ lẻ quanh khu vực TP. Hồ Chí Minh. Có thể nhận việc gấp trong ngày nếu khách cần xử lý sớm.', 'TP. Hồ Chí Minh', 10.7947009, 106.6570281, 20, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000062', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000062', '-', '')), 'Kiều Thị Ánh Tuyết', 'Chuyên sửa chữa hệ thống điện gia đình, 7 năm kinh nghiệm, xử lý nhanh gọn. Nhận thanh toán chuyển khoản hoặc tiền mặt đều được, có xuất hoá đơn nếu cần.', 'TP. Hồ Chí Minh', 10.8457169, 106.7583631, 30, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000063', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000063', '-', '')), 'Phan Thị Tuyền', 'Thợ điện dân dụng 0 năm, chuyên đi dây âm tường, lắp đèn, thay aptomat. Ưu tiên làm kỹ, không làm ẩu cho xong việc, dù mất thêm thời gian.', 'TP. Hồ Chí Minh', 10.7454450, 106.6926638, 30, 'VERIFIED', NOW(3), NOW(3)),
